# Cache writes of requests that follow a >=5-minute gap in the same agent, attributed to what the agent was waiting on:
# the target of the last wait_for/tail/grep in the tool call before the gap. Per run and per agent kind.
import json, glob, re, collections
from datetime import datetime
W='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows/'
def ts(s): return datetime.fromisoformat(s.replace('Z','+00:00'))
def kind(cmd):
    f=re.findall(r'wait_for\s+([^ ;&|\\"]+)',cmd)
    t=(f[-1] if f else cmd).lower()
    if re.search(r'pass-?(base|edit|a\b|b\b|e\b)|pass[abe]/|passes/|count-run|walk-pass|basea|baseb|count/|-pass\.txt|pass\.txt|3pass|tests-(before|after|base|edit)|corpus',t): return 'corpus pass'
    if re.search(r'tex|gensource|pdflatex|spec-build|build/',t): return 'spec build'
    if re.search(r'mg-|microgpt|mg/|mgcheck',t): return 'microGPT check'
    if re.search(r'ladder|subset',t): return 'ladder subset'
    if re.search(r'checker-count|cc-|distance|perdecl',t): return 'count/distance'
    if re.search(r'compileall|testfast|testsystem|gate|junit|cache|build|ant\b|rebuild|atomic',t): return 'build/test'
    return 'other'
tot=collections.Counter(); allcw=collections.Counter(); samples=collections.defaultdict(list)
perrun=collections.defaultdict(collections.Counter)
for m in sorted(glob.glob(W+'wf_*/agent-*.meta.json')):
    run=m.split('/')[-2]
    if run in ('wf_9b6732fc-64c','wf_576bd1f3-f0c'): continue
    desc=json.load(open(m)).get('description','')
    role=desc.split(':')[0] if desc else '?'
    a=m[:-10]; msgs={}; order=[]
    for l in open(a+'.jsonl'):
        if not l.strip(): continue
        j=json.loads(l)
        if j.get('type')!='assistant': continue
        mm=j['message']; mid=mm.get('id')
        if mid not in msgs: msgs[mid]={'t':ts(j['timestamp']),'cw':0,'cmd':''}; order.append(mid)
        msgs[mid]['cw']=max(msgs[mid]['cw'],(mm.get('usage') or {}).get('cache_creation_input_tokens',0) or 0)
        for c in mm.get('content',[]) if isinstance(mm.get('content'),list) else []:
            if isinstance(c,dict) and c.get('type')=='tool_use': msgs[mid]['cmd']+=' '+json.dumps(c.get('input',{}))
    allcw[role]+=sum(msgs[i]['cw'] for i in order)
    for k in range(1,len(order)):
        p=msgs[order[k-1]]; q=msgs[order[k]]
        if (q['t']-p['t']).total_seconds()>=300:
            kd=kind(p['cmd']); tot[(role,kd)]+=q['cw']; perrun[run][kd]+=q['cw']
            if kd=='other' and len(samples[role])<6: samples[role].append(p['cmd'][-200:])
print('all cache writes by role:', {k:'%.1fM'%(v/1e6) for k,v in allcw.most_common()}, 'sum %.1fM'%(sum(allcw.values())/1e6))
bykind=collections.Counter()
for (r,k),v in tot.items(): bykind[k]+=v
print('after-gap cw by what was awaited, all roles:', {k:'%.1fM'%(v/1e6) for k,v in bykind.most_common()}, 'sum %.1fM'%(sum(bykind.values())/1e6))
for r in ['rung','resume','skeptic','skeptic2','repair','review','gather','gate']:
    d={k:v for (rr,k),v in tot.items() if rr==r}
    if d: print(' ',r, {k:'%.1fM'%(v/1e6) for k,v in sorted(d.items(),key=lambda x:-x[1])})
print('per run corpus-pass after-gap cw:')
for run in sorted(perrun): print(' ',run, {k:'%.2fM'%(v/1e6) for k,v in perrun[run].most_common()})
for r,s in samples.items():
    for x in s[:3]: print('OTHER',r,x[-160:])
EOF
